function solve(x, y) {
  // t[i][j] = panjang LCS dari i karakter pertama x dan j karakter pertama y
  const t = Array.from({ length: x.length + 1 }, () => Array(y.length + 1).fill(0))
  for (let i = 1; i <= x.length; i++) {
    for (let j = 1; j <= y.length; j++) {
      if (x[i - 1] === y[j - 1]) {
        t[i][j] = t[i - 1][j - 1] + 1 // karakter sama: perpanjang LCS
      } else {
        t[i][j] = Math.max(t[i - 1][j], t[i][j - 1]) // beda: ambil yang terbaik
      }
    }
  }
  return t[x.length][y.length]
}
